use xiom.io;

type Counter = {
  value: Int;
  min: Int;
  max: Int;
  invariant: value >= min;
  invariant: value <= max;
}

fn Counter.increment(&mut self)
  requires: self.value < self.max;
  ensures: self.value == self@pre.value + 1;
{
  self.value = self.value + 1;
}

fn Counter.decrement(&mut self)
  requires: self.value > self.min;
  ensures: self.value == self@pre.value - 1;
{
  self.value = self.value - 1;
}

fn Counter.reset(&mut self)
  ensures: self.value == self.min;
{
  self.value = self.min;
}

fn main() -> Int {
  var c: Counter = Counter{ value: 0, min: 0, max: 10 };
  c.increment();
  c.increment();
  c.increment();
  c.increment();
  c.increment();
  c.decrement();
  c.decrement();
  c.reset();
  return c.value;
}
